use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_ids = input
        .as_array()
        .unwrap()
        .iter()
        .map(|&(priority, id)| (priority, id))
        .collect::<Vec<(i64, i64)>>()
        .sort_unstable_by(|&(p1, _), &(p2, _)| p2.cmp(&p1))
        .map(|(_, id)| id)
        .collect::<Vec<i64>>();

    serde_json::Value::Array(sorted_ids)
}
